class VideoSharingPlatform:
    def __init__(self):
        self.available = [0]
        self.next_id = 1
        self.videos = {}
        self.likes = defaultdict(int)
        self.dislikes = defaultdict(int)
        self.views = defaultdict(int)

    def upload(self, video):
        if self.available:
            vid = heapq.heappop(self.available)
        else:
            vid = self.next_id
            self.next_id += 1
        if not self.available:
            heapq.heappush(self.available, self.next_id)
            self.next_id += 1
        self.videos[vid] = video
        self.likes[vid] = 0
        self.dislikes[vid] = 0
        self.views[vid] = 0
        return vid

    def remove(self, videoId):
        if videoId in self.videos:
            del self.videos[videoId]
            heapq.heappush(self.available, videoId)

    def watch(self, videoId, startMinute, endMinute):
        if videoId not in self.videos:
            return '-1'
        self.views[videoId] += 1
        video = self.videos[videoId]
        end = min(endMinute, len(video) - 1)
        return video[startMinute:end+1]

    def like(self, videoId):
        if videoId in self.videos:
            self.likes[videoId] += 1

    def dislike(self, videoId):
        if videoId in self.videos:
            self.dislikes[videoId] += 1

    def getLikesAndDislikes(self, videoId):
        if videoId not in self.videos:
            return [-1]
        return [self.likes[videoId], self.dislikes[videoId]]

    def getViews(self, videoId):
        if videoId not in self.videos:
            return -1
        return self.views[videoId]

