from sortedcontainers import SortedList
class CountIntervals:
    def __init__(self):
        self.intervals = SortedList()
        self.cnt = 0

    def add(self, left, right):
        # Find overlapping intervals
        new_left, new_right = left, right
        to_remove = []
        idx = self.intervals.bisect_left((left,))
        if idx > 0:
            idx -= 1
        while idx < len(self.intervals):
            l, r = self.intervals[idx]
            if l > right + 1:
                break
            if r < left - 1:
                idx += 1
                continue
            to_remove.append((l, r))
            new_left = min(new_left, l)
            new_right = max(new_right, r)
            idx += 1
        for iv in to_remove:
            self.intervals.remove(iv)
            self.cnt -= (iv[1] - iv[0] + 1)
        self.intervals.add((new_left, new_right))
        self.cnt += new_right - new_left + 1

    def count(self):
        return self.cnt

from collections import defaultdict, deque
class Solution:
    def closestNode(self, n, edges, query):
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        LOG = 17
        depth = [0] * n
        parent = [[0]*n for _ in range(LOG)]
        # BFS to set up parent and depth
        visited = [False] * n
        visited[0] = True
        q = deque([0])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    depth[v] = depth[u] + 1
                    parent[0][v] = u
                    q.append(v)
        for k in range(1, LOG):
            for v in range(n):
                parent[k][v] = parent[k-1][parent[k-1][v]]
        def lca(u, v):
            if depth[u] < depth[v]:
                u, v = v, u
            diff = depth[u] - depth[v]
            for k in range(LOG):
                if (diff >> k) & 1:
                    u = parent[k][u]
            if u == v:
                return u
            for k in range(LOG-1, -1, -1):
                if parent[k][u] != parent[k][v]:
                    u = parent[k][u]
                    v = parent[k][v]
            return parent[0][u]
        def dist(u, v):
            return depth[u] + depth[v] - 2 * depth[lca(u, v)]
        ans = []
        for s, e, node in query:
            l = lca(s, e)
            l1 = lca(s, node)
            l2 = lca(e, node)
            # Closest node on path s->e to node
            candidates = [l, l1, l2]
            best = min(candidates, key=lambda x: dist(x, node))
            ans.append(best)
        return ans

