class Solution:
    def maximumBags(self, capacity, rocks, additionalRocks):
        remaining = sorted(c - r for c, r in zip(capacity, rocks))
        count = 0
        for need in remaining:
            if additionalRocks >= need:
                additionalRocks -= need
                count += 1
            else:
                break
        return count

class Solution:
    def minimumLines(self, stockPrices):
        stockPrices.sort()
        n = len(stockPrices)
        if n <= 1:
            return 0
        lines = 1
        for i in range(2, n):
            # Compare slopes: (y2-y1)*(x3-x2) != (y3-y2)*(x2-x1)
            x1, y1 = stockPrices[i-2]
            x2, y2 = stockPrices[i-1]
            x3, y3 = stockPrices[i]
            if (y2-y1)*(x3-x2) != (y3-y2)*(x2-x1):
                lines += 1
        return lines
